-- For God so loved the world, that He gave His only begotten Son,
-- that all who believe in Him should not perish but have everlasting life.
-- — John 3:16

-- ROMANS - IND Combined
-- Generated: 2026-01-29T06:49:41.144Z

-- c004-v001: Apa jadi akan–kita–katakan, mendapat Abraham, – nenek–moyang kita, menurut daging?
-- c004-v002: Karena–jika – Abraham dari perbuatan dibenarkan, ia–memiliki kemegahan, tetapi tidak di–hadapan Allah.
-- c004-v003: Apa karena – Kitab–Suci berkata? Percaya tetapi Abraham kepada– Allah, dan diperhitungkan kepadanya sebagai kebenaran.
-- c004-v004: Kepada– tetapi yang–bekerja, – upah tidak diperhitungkan menurut kasih–karunia, tetapi menurut kewajiban.
-- c004-v005: Kepada– tetapi yang–tidak bekerja, percaya tetapi kepada Dia–yang membenarkan orang–yang fasik, diperhitungkan – iman –nya sebagai kebenaran,
-- c004-v006: sebagaimana juga Daud menyatakan – kebahagiaan – manusia kepada–siapa – Allah memperhitungkan kebenaran terpisah–dari perbuatan:
-- c004-v007: Berbahagialah yang diampuni – pelanggaran, dan yang ditutupi, – dosa-dosa;
-- c004-v008: berbahagialah orang yang, tidak – memperhitungkan Tuhan dosa.
-- c004-v009: – Kebahagiaan jadi ini, atas – yang–bersunat, atau juga atas – yang–tidak–bersunat? Kami–berkata karena, Diperhitungkan kepada– Abraham – iman sebagai kebenaran.
-- c004-v010: Bagaimana jadi diperhitungkan? Ketika–dalam sunat ada, atau ketika–dalam ketidak-bersunat? Bukan dalam sunat, tetapi dalam ketidak-bersunat.
-- c004-v011: Dan tanda ia–menerima sunat, meterai – kebenaran – iman yang dalam – ketidak-bersunat, supaya – menjadi dia bapa semua orang–yang percaya melalui ketidak-bersunat, supaya – diperhitungkan [juga] kepada–mereka – kebenaran;
-- c004-v012: dan bapa sunat, bagi–mereka–yang bukan dari sunat saja, tetapi juga bagi–mereka–yang mengikuti – jejak – dalam ketidak-bersunat iman, – bapa kita Abraham.
-- c004-v013: Karena–bukan – melalui hukum – janji kepada– Abraham, atau kepada– keturunan –nya, – ahli–waris ia menjadi dunia, tetapi melalui kebenaran iman.
-- c004-v014: Karena–jika – – dari hukum ahli–waris, dikosongkan – iman, dan dibatalkan – janji.
-- c004-v015: – Karena hukum murka menghasilkan; di–mana tetapi tidak–ada – hukum, tidak–ada–juga pelanggaran.
-- c004-v016: Karena itu dari iman, supaya menurut kasih–karunia, supaya – menjadi pasti, – janji kepada–semua – keturunan, bukan kepada– dari – hukum saja, tetapi juga kepada– dari iman Abraham, yang adalah bapa semua kita,
-- c004-v017: sebagaimana ada–tertulis, bahwa Bapa banyak bangsa telah–Kujadikan engkau. Di–hadapan Dia–yang ia–percaya Allah, yang menghidupkan – orang–mati, dan memanggil – yang–tidak ada seolah-olah ada;
-- c004-v018: yang melampaui pengharapan, dalam pengharapan percaya, supaya – menjadi ia bapa banyak bangsa, menurut apa–yang difirmankan, Demikianlah akan–ada – keturunan –mu.
-- c004-v019: Dan tidak menjadi–lemah dalam– iman, ia–memperhatikan – sendiri tubuh [sudah] yang–mati, seratus–tahun kira-kira ada, dan – kematian – rahim Sara,
-- c004-v020: kepada tetapi – janji – Allah, tidak ia–ragu karena– ketidak-percayaan, tetapi dikuatkan dalam– iman, memberikan kemuliaan kepada– Allah,
-- c004-v021: dan yakin–sepenuhnya bahwa apa–yang dijanjikan, berkuasa Dia–adalah juga untuk–melakukan.
-- c004-v022: Karena–itu juga diperhitungkan kepadanya sebagai kebenaran.
-- c004-v023: Tidak ditulis, tetapi untuk– dia saja, bahwa diperhitungkan kepadanya,
-- c004-v024: tetapi juga untuk– kita, kepada–siapa akan diperhitungkan, kita–yang percaya kepada Dia–yang membangkitkan Yesus, – Tuhan kita, dari orang–mati,
-- c004-v025: yang diserahkan karena – pelanggaran kita, dan dibangkitkan karena – pembenaran kita.

